from .ranges import bounds, InvalidRange


def serve(data, range_header=None):
    if range_header is not None:
        length = len(data)
        try:
            start, end = bounds(range_header, length)
        except InvalidRange:
            return 416, {'Content-Range': f'bytes */{length}'}, b''
        body = data[start:end + 1]
        return 206, {
            'Content-Range': f'bytes {start}-{end}/{length}',
            'Content-Length': str(len(body)),
        }, body
    return 200, {'Content-Length': str(len(data))}, data
